"use strict";(globalThis.webpackChunkuniwahl_doku||=[]).push([[5659],{695(e,n,i){i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>l,default:()=>o,frontMatter:()=>a,metadata:()=>r,toc:()=>u});const r=JSON.parse('{"id":"releases/6.3","title":"Version 6.3","description":"\ud83d\ude80 Dieses Release enth\xe4lt eine Reihe an Optimierungen und neuen Features, um die Wahlorganisation noch effizienter zu gestalten.","source":"@site/docs/releases/6.3.md","sourceDirName":"releases","slug":"/releases/6.3","permalink":"/uniwahl-doku/pr-preview/pr-2/releases/6.3","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Version 6.3"},"sidebar":"doku","previous":{"title":"Version 6.4","permalink":"/uniwahl-doku/pr-preview/pr-2/releases/6.4"},"next":{"title":"Version 6.2","permalink":"/uniwahl-doku/pr-preview/pr-2/releases/6.2"}}');var t=i(4848),s=i(8453);const a={title:"Version 6.3"},l=void 0,d={},u=[];function h(e){const n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.p,{children:"\ud83d\ude80 Dieses Release enth\xe4lt eine Reihe an Optimierungen und neuen Features, um die Wahlorganisation noch effizienter zu gestalten."}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Komplette Wahl importieren \u2013 Struktur und Wahlvorschl\xe4ge"}),": Die neueste Funktion \u201eImportiere Wahl\u201c erm\xf6glicht es, eine komplette Wahl \u2013 einschlie\xdflich ihrer Struktur und aller Wahlvorschl\xe4ge \u2013 mit nur wenigen Klicks zu importieren. Damit k\xf6nnen Wahlen effizienter organisiert werden. Statt jede Wahl von Grund auf neu erstellen zu m\xfcssen, k\xf6nnen Organisatoren jetzt die Struktur und alle Wahlvorschl\xe4ge aus einer bestehenden Wahlvorschlagsdatei \xfcbernehmen. Zudem k\xf6nnen die Wahlordnungskonfiguration, Layouts und Texte aus einer bestehenden WHL-Datei (Template) geladen werden. Das spart nicht nur wertvolle Zeit, sondern reduziert auch das Risiko von Fehlern, die beim manuellen Einpflegen von Daten entstehen k\xf6nnen. Organisatoren k\xf6nnen sich nun noch mehr auf strategische Aspekte der Wahlplanung konzentrieren, anstatt Zeit mit repetitiven Aufgaben zu verbringen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Mehrsprachiger Wahlimport"}),": Die Organisation von Wahlen, insbesondere in einem internationalen oder mehrsprachigen Kontext, kann eine komplexe Herausforderung darstellen. Der mehrsprachige Wahlimport erm\xf6glicht es den Organisatoren, Strukturdaten (Gremien- und Gruppennamen zahlreicher Gruppen) in verschiedenen Sprachen zu importieren und zu verwalten, was den Prozess nicht nur effizienter, sondern auch inklusiver macht. So k\xf6nnen Stimmzettel in mehreren Sprachen sowohl in Papier- als auch elektronischer Form schnell ausgegeben werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Neues Men\xfc des Online-Wahlsystems - \u201eOWS\u201c statt \u201eeWAHL\u201c (End of life)"}),": Im Zuge der kontinuierlichen Weiterentwicklung und Optimierung unserer Softwarel\xf6sungen freuen wir uns, Ihnen eine weitere Neuerung in uniWAHL vorstellen zu d\xfcrfen: das neue Men\xfc des uniWAHL Online-Wahlsystem \u201eOWS\u201c. Diese Aktualisierung ersetzt das bisher bekannte \u201eeWAHL\u201c-Add-on und markiert nicht nur einen Namenwechsel, sondern auch eine erhebliche Verbesserung in Funktionalit\xe4t und Benutzererfahrung. Mit uniWAHL OWS k\xf6nnen die Daten aus der uniWAHL Kernsoftware nahtlos an ein Online-Wahlsystem \xfcbergeben werden, diesen Prozess werden wir schrittweise weiter automatisieren. Die Abl\xf6sung von \u201eeWAHL\u201c durch \u201eOWS\u201c tr\xe4gt der Notwendigkeit Rechnung, zuk\xfcnftige technologische Entwicklungen und Anforderungen leichter integrieren zu k\xf6nnen. Wir warten und unterst\xfctzen daher die Schnittstelle zu anderen Online-Wahlsystemen nur noch f\xfcr Bestandskunden mit Wartungsvertrag."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Live-Preview der Online-Wahlkabine"}),": Diese Neuerung stellt einen bedeutenden Schritt nach vorn dar, um den Organisator",":innen"," von Wahlen nicht nur Zeit und Ressourcen zu sparen, sondern auch eine nahtlose und fehlerfreie Wahlumgebung zu gew\xe4hrleisten. Eines der h\xe4ufigsten Probleme bei der Organisation von Online-Wahlen ist die Unsicherheit dar\xfcber, wie die Wahlkabine f\xfcr die W\xe4hler aussieht und funktioniert. Der Kern unserer neuen Funktion liegt in ihrer F\xe4higkeit, eine Echtzeitvorschau der Online-Wahlkabine zu bieten, bevor diese f\xfcr die W\xe4hler zug\xe4nglich gemacht wird. Diese Live-Preview erm\xf6glicht es den Wahlorganisatoren, die Gestaltung der Wahlkabine genau zu \xfcberpr\xfcfen, einschlie\xdflich der Anordnung von Wahlm\xf6glichkeiten, Textformatierungen und weiteren interaktiven Elementen. Somit kann sichergestellt werden, dass alles genauso aussieht und funktioniert, wie es beabsichtigt ist, bevor die Wahl offiziell startet."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"W\xe4hlergruppe kontrollieren als \xfcbersichtlicher Dialog"}),": Bisherige Versionen von uniWAHL erforderten, dass die Verwaltung von sog. W\xe4hlergruppen durch mehrschrittige Prozesse erfolgte, die nicht nur zeitintensiv, sondern auch fehleranf\xe4llig waren. Nutzer mussten verschiedene Fenster navigieren, um W\xe4hlergruppen zu \xfcberpr\xfcfen und zu verwalten. Durch die Implementierung eines Dialogfensters f\xfcr die Kontrolle von W\xe4hlergruppen l\xf6st uniWAHL ein h\xe4ufig auftretendes Problem: die Komplexit\xe4t der Zuordnung von Stimmzetteln. Nutzer k\xf6nnen nun mit wenigen Klicks die \xdcbersicht bewahren und \xc4nderungen vornehmen, was die Software insgesamt effektiver macht."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"W\xe4hlergruppen kodieren direkt im Wahlbereich-Dialog"}),": Die Bedeutung dieser Funktion l\xe4sst sich am besten verstehen, indem man sich das herk\xf6mmliche Vorgehen bei der Organisation von Online-Wahlen vor Augen f\xfchrt. Bisher mussten W\xe4hlergruppen zuerst kodiert und dann manuell den entsprechenden Wahlbereichen zugeordnet werden. Dieser Prozess war z.T. schwer verst\xe4ndlich, fehleranf\xe4llig und zeitaufwendig, da er mehrere Schritte und oft auch das Hin- und Herwechseln zwischen verschiedenen Dialogen erforderte. Mit der Einf\xfchrung der M\xf6glichkeit, W\xe4hlergruppen direkt im Wahlbereich-Dialog einzugeben bzw. aus dem Gremium- und Gruppenk\xfcrzel automatisch zu generieren, \xe4ndert sich dieses Szenario grundlegend. Nutzer k\xf6nnen nun mit einem einzigen Klick W\xe4hlergruppen im Wahlbereich definieren und sehen diese pr\xe4senter angezeigt. Dies vereinfacht den Prozess und f\xfchrt zu einer Zeitersparnis."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Write-in-Felder f\xfcr Nominierungen \u2013 Bildausschnitte im Ausz\xe4hlungsprotokoll (uniSCAN)"}),": Die Write-in-Felder f\xfcr Nominierungen erm\xf6glichen es den W\xe4hlenden, Kandidat",":innen"," direkt auf dem Stimmzettel zu nominieren, indem sie deren Namen handschriftlich eintragen k\xf6nnen. Dies er\xf6ffnet M\xf6glichkeiten f\xfcr spontane Nominierungen vor und w\xe4hrend der Wahl. Die Integration von Bildausschnitten dieser Felder im Ausz\xe4hlungsprotokoll (uniSCAN) stellt einen weiteren Vorteil dar. Durch die visuelle Dokumentation und \xdcberpr\xfcfbarkeit aller handschriftlichen Eintr\xe4ge wird eine h\xf6here Transparenz und einfache Nachverarbeitung gew\xe4hrleistet. Die Write-in-Felder passen sich nun besser an die Spaltenbreiten des Stimmzettels an, so dass ausreichend Platz f\xfcr handschriftliche Nominierungen vorhanden ist."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Stimmen f\xfcr nachnominierte Personen aggregieren (nur online)"}),": Das Aggregieren von Stimmen f\xfcr nachnominierte Personen ist eine Weiterentwicklung, die das Verwalten von Online-Wahlen ohne Bindung an Wahlvorschl\xe4ge vereinfacht. Fr\xfcher mussten Wahlorganisator",":innen"," die Stimmen f\xfcr nachnominierte Personen manuell sammeln und zusammenf\xfchren, ein Prozess, der sehr zeitaufwendig war. Mit der neuen Funktion von uniWAHL wird dieser Prozess durch einen intelligenten Algorithmus automatisiert, der Stimmen basierend auf einem String-Vergleich identifiziert und aggregiert. Es m\xfcssen dabei alle Felder eines nachtr\xe4glich eingereichten Wahlvorschlags \xfcbereinstimmen, damit die Stimmen aufsummiert werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"Nominierten\xfcbersicht in XLSX ausgeben (nur online)"}),": W\xe4hrend des Imports von Rohdaten aus dem uniWAHL Onlinewahlsystem (OWS) werden Daten zur Nominierung (Write-In-Felder) nun noch besser ausgewertet. Der Export einer Nominierten\xfcbersicht in das XLSX-Format automatisiert einen Prozess, der zuvor manuelle Dateneingabe erforderte. Die XLSX-Ausgabe in uniWAHL bietet eine umfassende Darstellung aller (Nach-)Nominierungen in einem klaren und \xfcbersichtlichen Format, so dass die Daten der Kandidierenden leicht validiert und wieder in uniWAHL importiert werden k\xf6nnen."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Write-in-Felder passen sich an Stimmzettel-Layout an"}),": Diese Funktion wurde entwickelt, um ein h\xe4ufig auftretendes Problem bei der Durchf\xfchrung von Wahlen ohne Bindung an Wahlvorschl\xe4ge zu l\xf6sen: die Herausforderung, Stimmzettel so zu gestalten, dass sie sowohl benutzerfreundlich sind als auch eine effiziente Datenerfassung erm\xf6glichen. Durch die automatische Anpassung der Write-in-Felder an das Layout der Kandidatenfelder des Stimmzettels wird sichergestellt, dass bei nominierten Personen die Daten erfasst werden k\xf6nnen, die zur sp\xe4teren Darstellung auf dem Stimmzettel erforderlich sind."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Custom CSS im Online-Layout"}),": Durch die Einf\xfchrung dieser Funktion wird es m\xf6glich, das Erscheinungsbild von uniWAHL-Online-Wahlkabinen anzupassen, indem spezifische CSS-Parameter direkt im Layout hinterlegt werden k\xf6nnen. Dies bedeutet, dass einmal festgelegte Designs und Stile automatisch und konsistent auf zuk\xfcnftige Projekte und Wahlen angewendet werden k\xf6nnen, ohne dass weitere manuelle Anpassungen notwendig sind. Diese Funktion adressiert das h\xe4ufig auftretende Problem, dass Benutzer",":innen"," ihre individuellen Designpr\xe4ferenzen und Markenidentit\xe4ten in den Wahlprozessen konsistent und effizient integrieren m\xf6chten, ohne bei jeder Nutzung der Software erneut Anpassungen vornehmen zu m\xfcssen. Die CSS-Parameter werden sowohl in der Live-Vorschau als auch in der Erzeugung der Stimmzettel zur Online-Wahl angewandt."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Wahlbeteiligungs\xfcbersicht mit Zusatzfeld \u201eW\xe4hlergruppe\u201c"}),": Die Bereitstellung einer erweiterten Wahlbeteiligungs\xfcbersicht in uniWAHL OWS ist spezifisch darauf ausgerichtet, den Wahlorganisator",":innen"," einen tieferen Einblick in die demografische Verteilung der pseudonyme W\xe4hlerschaft zu erm\xf6glichen, wie beispielsweise nach Fachbereich, Statusgruppe oder Geschlecht. Diese Funktion adressiert ein h\xe4ufig aufgetretenes Bed\xfcrfnis nach detaillierteren Analysem\xf6glichkeiten der Wahlbeteiligung. Die W\xe4hlergruppe wird nun direkt in die Wahlbeteiligungs\xfcbersicht eingetragen. Die M\xf6glichkeit, diese Daten anschlie\xdfend \xfcber einen CSV-Download abzurufen, stellt eine flexible und benutzerfreundliche L\xf6sung dar, die es Wahlorganisator",":innen"," erlaubt, die Daten nach Bedarf weiter zu analysieren und zu pr\xe4sentieren."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Einreichen von Wahlvorschlagslisten in uniWAHL OWS"}),": Die neue Funktion \u201eNominierung erzeugen\u201c erm\xf6glicht es den Nutzer",":innen",", einfache Wahlvorschlagslisten direkt \xfcber ein uniWAHL Online-Wahlsystem einzureichen. Es k\xf6nnen neben Kandidaten- auch Listenwahlvorschl\xe4ge erfasst und anschlie\xdfend direkt in uniWAHL importiert werden. Es findet bislang keine automatische \xdcberpr\xfcfung der Dateneingaben auf Vollst\xe4ndigkeit und Plausibilit\xe4t statt, die Anzahl und Bezeichnungen der Datenfelder k\xf6nnen aber verpflichtend angeboten werden und in Ihrer Zeichenl\xe4nge begrenzt. Die Feldbezeichner der Eingabefelder werden mehrsprachig angeboten."]}),"\n",(0,t.jsxs)(n.li,{children:["\u2728",(0,t.jsx)(n.strong,{children:"OWS: Authentifizierung zur Online-Wahl mit OpenID"}),": Der Einsatz von OpenID, einem weit verbreiteten Standard f\xfcr Online-Identit\xe4ten, gew\xe4hrleistet nicht nur ein hohes Ma\xdf an Sicherheit, sondern auch eine nahtlose Integration in bestehende IT-Infrastrukturen. Diese innovative Funktion erm\xf6glicht es den W\xe4hler",":innen",", sich sicher und unkompliziert f\xfcr die Teilnahme an Online-Wahlen zu authentifizieren. Die Vorteile dieser Funktion sind vielf\xe4ltig. Zum einen erh\xf6ht sie die Sicherheit der Wahl, da OpenID robuste Mechanismen zur Verifizierung der Identit\xe4t der Benutzer bereitstellt. Zum anderen f\xf6rdert sie die Wahlbeteiligung, da der vereinfachte Zugang es mehr berechtigten Teilnehmern erm\xf6glicht, ihre Stimme abzugeben. Dar\xfcber hinaus unterst\xfctzt die Integration von OpenID die Kompatibilit\xe4t mit einer Vielzahl von Identit\xe4tsanbietern, was die Flexibilit\xe4t f\xfcr Organisationen und Endnutzer erh\xf6ht."]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"\u2699\ufe0fWeitere \xc4nderungen und Fehlerbehebungen"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\u2705Die Verwendung von Benutzerkennung und Passwort ist vielen Nutzer",":innen"," aus ihrem allt\xe4glichen Umgang mit digitalen Diensten vertrauter. Die Bezeichnungen \u201ePIN\u201c und \u201eTAN\u201c zur Online-Authentifizierung k\xf6nnen daher ab sofort ge\xe4ndert werden."]}),"\n",(0,t.jsxs)(n.li,{children:["\ud83d\udc1eEs wurde ein Problem adressiert, das bei der Organisation von Wahlen in der Vergangenheit h\xe4ufig auftrat: die korrekte \xdcbertragung der Rangreihenfolge von Kandidat",":innen"," aus verschiedenen Listen in ein Mehrheitswahlsystem."]}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs wurden verschiedene Probleme behoben, die die mehrsprachige Vorschau der Online-Wahlkabine betrafen."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs wurde ein Anzeige-Problem behoben, dass beim \u201eStatus zur\xfccksetzen\u201c auftreten konnte, da diese Eingaben nun direkt gespeichert werden."}),"\n",(0,t.jsx)(n.li,{children:'\ud83d\udc1eEs wurde ein Problem behoben, dass daf\xfcr sorgte, dass bei \u201eKandidateneingabe fertig (Alle Bereiche) die Wahlordnungseinstellung "Mehrheitswahl, wenn 1 Liste" nicht ber\xfccksichtigt wurde.'}),"\n",(0,t.jsx)(n.li,{children:'\ud83d\udc1eEs wurde ein Problem behoben, dass daf\xfcr sorgte, dass bei \u201eKandidateneingabe fertig (Alle Bereiche) die Wahlordnungseinstellung "Kandidatenzahl <= Sitze: Ohne Wahl gew\xe4hlt" nicht ber\xfccksichtigt wurde.'}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs war bisher nicht m\xf6glich, alle Gremien einer WHL-Datei zu l\xf6schen. Dies wurde nun ge\xe4ndert."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs konnte vorkommen, dass Feldbezeichner in der Personendatenkonfiguration trotz des Aufrufs von \u201eAus Auswahl l\xf6schen\u201c in den Alias-Namen erhalten blieben. Dieser Fehler wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Election IDs von Online-Wahlen k\xf6nnen nun fortlaufend hochgez\xe4hlt werden."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Bei der Erzeugung von Stimmzetteln im JSON-Format wird nun auch das W\xe4hlerverzeichnis in CSV ausgegeben, so dass dieses nachtr\xe4glich der Wahl im uniWAHL OWS hinzugef\xfcgt werden kann, wenn sich z.B. kurzfristig noch \xc4nderungen ergeben."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eEs wurde ein Problem behoben, dass eine Erzeugung von Stimmzetteln in uniWAHL OWS verhinderte, wenn mehr Stimmen als Kandidierende im Wahlbereich vorhanden waren."}),"\n",(0,t.jsx)(n.li,{children:"\ud83d\udc1eDie Stimmzettelkennung (zur besseren \xdcbersicht in der Ausgabe von Papierstimmzettel) konnte nicht gespeichert werden. Dieses Problem wurde behoben."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Lizenzbestimmungen wurden angepasst."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Anleitung zur Nutzung von W\xe4hlergruppen Men\xfc \u201eOWS\u201c > \u201eW\xe4hlergruppen-Anleitung\u201c wurde ausgetauscht."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Begrifflichkeit \u201eeWAHL\u201c wurde in allen Unterlagen durch \u201eOWS\u201c ersetzt."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Die Begrifflichkeit \u201eNachnominierte\u201c wurde in allen Unterlagen durch \u201eNominierte\u201c ersetzt, um der Vorabnominierung besser Rechnung zu tragen."}),"\n",(0,t.jsx)(n.li,{children:"\u2705Der Aufruf \u201eImportiere Stimmen (Roh)\u201c im Men\xfc \u201eOWS\u201c bzw. \u201eeWAHL\u201c wurde in \u201eImportiere Rohdaten\u201c umbenannt, um dem Sachverhalt Rechnung zu tragen, dass nicht nur Stimmen, sondern auch nominierte Personen importiert werden."}),"\n"]})]})}function o(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h(e)}},8453(e,n,i){i.d(n,{R:()=>a,x:()=>l});var r=i(6540);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function l(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}}}]);